mapper.select:
SELECT	SEQ AS seq, IFNULL(INET6_NTOA(IP), INET_NTOA(IP)) AS ip, DATE_FORMAT(CTIME, '%Y-%m-%d %T' ) AS ctime, MODULE as module, SERVICE AS service, TYPE AS type, INFO AS info
FROM	XCNLOG
WHERE	1=1

AND		CTIME BETWEEN STR_TO_DATE( CONCAT( #{startDt}, '000000'), '%Y%m%d%H%i%s') AND STR_TO_DATE( CONCAT(#{endDt},'235959'), '%Y%m%d%H%i%s')


AND		IP LIKE CONCAT( '%', #{ip}, '%' )


AND		SERVICE = #{service}


AND		TYPE = #{type}

ORDER	BY SEQ DESC

LIMIT	${offset}, ${limit}
